const adjacent=p=>{const x=cols.indexOf(p[0]),y=+p[1];return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,c])=>a>=0&&a<9&&c>=1&&c<=9).map(([a,c])=>cols[a]+c);};
const seen=new Set(),groups=[],regions=[];
for(const p of Object.keys(b)) {if(seen.has(p))continue;const color=b[p],q=[p],stones=[],lib=new Set(),boundary=new Set();seen.add(p);while(q.length){const a=q.pop();stones.push(a);for(const n of adjacent(a)){if(b[n]===color&&!seen.has(n)){seen.add(n);q.push(n);}else if(b[n]!==color){if(b[n]===".")lib.add(n);else boundary.add(n);}}}
