const counts={X:0,O:0,empty:0};Object.values(b).forEach(v=>v==="."?counts.empty++:counts[v]++);
const area={X:counts.X,O:counts.O,neutral:0};for(const r of regions)if(r.owners.length===1)area[r.owners[0]]+=r.points.length;else area.neutral+=r.points.length;
