const k=t.match(/Ko point: ([A-HJ][1-9]|none)/);if(!k||k[1]!==(ko||"none"))errors.push({snapshot:checks.length,ko});
checks.push({kind:snap.kind,after:moves.length,boardMatched:true,captures:{...captures},ko});}
return{ok:errors.length===0,errors,moves,captureEvents,snapshots:checks.length,checks,final:inspect(log.snapshots.at(-1).raw)};
}`;
